INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('17b18678-1ec7-4938-8e2a-d696576e0c23'::uuid, 'Geography', 'Unit 1', 'Molarum Grade 10 — Geography Unit 1: Landforms of Africa', 'Source-grounded Molarum Grade 10 Geography questions for Unit 1: Landforms of Africa.') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('7d173b05-f36d-46d1-894c-bdb6df71f51d'::uuid, '17b18678-1ec7-4938-8e2a-d696576e0c23'::uuid, 'multiple_choice', 'Which continent is the largest by area according to the textbook?', 'Asia', 'The excerpt lists the continents from largest to smallest and places Asia first, making it the largest continent by area.', 0),('cc4da093-e7fd-4bf0-8547-348f0a396681'::uuid, '17b18678-1ec7-4938-8e2a-d696576e0c23'::uuid, 'multiple_choice', 'Which of the following is NOT listed as one of the three major landforms of the world?', 'Rivers', 'The excerpt states the three major landforms are mountains, plateaus, and plains; rivers are not listed among these three major landforms.', 1),('a6c96327-67a4-4fb9-84d4-32c19819e66f'::uuid, '17b18678-1ec7-4938-8e2a-d696576e0c23'::uuid, 'multiple_choice', 'What percentage of the Earth’s surface do the oceans cover as given in the text?', '71%', 'The excerpt states that the oceans together cover seventy one percent of the Earth.', 2),('56f4609c-c188-44aa-82e9-fb835968b694'::uuid, '17b18678-1ec7-4938-8e2a-d696576e0c23'::uuid, 'multiple_choice', 'Which ocean is described in the text as both the largest and the deepest?', 'Pacific Ocean', 'The excerpt states the Pacific Ocean is both the largest and the deepest ocean, covering one-third of the Earth’s surface.', 3),('16f90672-9a2a-4807-8dab-928e5f37a67b'::uuid, '17b18678-1ec7-4938-8e2a-d696576e0c23'::uuid, 'multiple_choice', 'Which definition matches an island as given in the excerpt?', 'A piece of ground completely surrounded by water', 'The excerpt defines an island as a piece of ground that is completely surrounded by water.', 4),('f2bfbb74-8aa6-455d-8986-1db3a651fea6'::uuid, '17b18678-1ec7-4938-8e2a-d696576e0c23'::uuid, 'multiple_choice', 'Which features are cited as resulting from external processes (erosion by water and wind)?', 'Gullies and river valleys', 'The excerpt explains that erosion by water and wind (external processes) can erode land and create minor landforms like gullies and river valleys.', 5),('63a4b050-67c4-4fda-8911-9f52419f5330'::uuid, '17b18678-1ec7-4938-8e2a-d696576e0c23'::uuid, 'multiple_choice', 'Which three are listed as the major landforms of the world in the textbook?', 'Mountains, Plateaus, Plains', 'The excerpt explicitly states that mountains, plateaus, and plains are the three major types of landforms.', 6),('b8b9e636-c1db-4fb7-80d6-39c259a2e1f9'::uuid, '17b18678-1ec7-4938-8e2a-d696576e0c23'::uuid, 'multiple_choice', 'Which of the following is given as an example of a peninsula in the text?', 'Italy', 'The excerpt gives Italy (and Florida) as well-known examples of peninsulas, land surrounded by water on three sides and connected to the mainland on the fourth.', 7),('91c3084e-6023-48ad-87c7-40f6c078cae9'::uuid, '17b18678-1ec7-4938-8e2a-d696576e0c23'::uuid, 'multiple_choice', 'Which term best describes a large area of flat low land with no hills or mountains?', 'Plain', 'The excerpt defines plains as large areas of flat low land with no hills or mountains in them.', 8),('c3fd926e-de5d-4630-8cc5-24009142a673'::uuid, '17b18678-1ec7-4938-8e2a-d696576e0c23'::uuid, 'multiple_choice', 'Which word in the excerpt refers to a narrow strip of land with water on both sides that connects two larger land areas?', 'Isthmus', 'The excerpt defines an isthmus as a narrow strip of land with water on both sides connecting two larger pieces of land and gives the Isthmus of Panama as an example.', 9),('4213bac6-9ef5-4522-8e7f-2b4b4dc9e82a'::uuid, '17b18678-1ec7-4938-8e2a-d696576e0c23'::uuid, 'multiple_choice', 'In the Sahara, a great sand sea formed by reddish sand dunes is called what?', 'Erg', 'The excerpt explains that the reddish sand dunes of the Sahara make up a great sand sea called an erg, whereas a reg is a desert pavement of pebbles.', 10),('d770a884-80da-400b-854f-e1bdc34bc586'::uuid, '17b18678-1ec7-4938-8e2a-d696576e0c23'::uuid, 'multiple_choice', 'Which group of countries is listed as making up the Congo Basin of the Tropical Rainforest?', 'Cameroon, Central African Republic, Republic of the Congo, Democratic Republic of the Congo, Gabon, Equatorial Guinea', 'The excerpt lists those six countries specifically as making up the Congo Basin of the Tropical Rainforest.', 11),('efb3f62a-46ac-4522-8c7c-979714400a19'::uuid, '17b18678-1ec7-4938-8e2a-d696576e0c23'::uuid, 'multiple_choice', 'How does the excerpt describe the Sahel region?', 'A vast semiarid transition zone south of the Sahara', 'The excerpt describes the Sahel as a vast semiarid region south of the Sahara that forms a transitional zone and spreads west to east across northern parts of several countries.', 12),('9e1fafac-7928-442a-801c-19b03fa657b4'::uuid, '17b18678-1ec7-4938-8e2a-d696576e0c23'::uuid, 'multiple_choice', 'Which description fits the Savanna region in Africa as given in the text?', 'Tropical grassland with few trees and drought-resistant species', 'The excerpt states the Savanna is a tropical grassland with few trees and shrubs and that trees are drought resistant and often shed leaves in the dry season.', 13),('d7efa71a-c5a5-4184-87c6-f1b4bbe43891'::uuid, '17b18678-1ec7-4938-8e2a-d696576e0c23'::uuid, 'multiple_choice', 'Which statement best characterizes the tropical rainforest climate in the excerpt?', 'Rainfall exceeds 2000 to 2250 millimeters annually and is evenly distributed', 'The excerpt indicates the rainforest climate is wet all year or with a short dry season, and annual rainfall exceeds 2000 to 2250 millimeters, evenly distributed.', 14),('b5b7de98-e9db-449d-8593-f59ed9a8963d'::uuid, '17b18678-1ec7-4938-8e2a-d696576e0c23'::uuid, 'multiple_choice', 'According to the text, the Rift Valley of East Africa was formed by which geological process?', 'Normal faulting', 'The excerpt explains the Rift Valley was formed by normal faulting as the land stretched and blocks dropped to form a graben between faults.', 15),('8261b0bf-6202-4478-8e20-606041034a4f'::uuid, '17b18678-1ec7-4938-8e2a-d696576e0c23'::uuid, 'multiple_choice', 'Which ocean current is mentioned as having influenced the formation of the Namib Desert?', 'Benguela', 'The excerpt states the Namib Desert was formed partly because of the cold ocean current of Benguela that borders the area.', 16),('88256b4b-efdf-4031-8563-0d7a0de912cc'::uuid, '17b18678-1ec7-4938-8e2a-d696576e0c23'::uuid, 'multiple_choice', 'The Atlas Mountains form a high divide between which two geographic features?', 'Mediterranean Sea and the Sahara Desert', 'The excerpt explains the Atlas topography forms a high divide between the Mediterranean Sea in the north and the Sahara Desert in the south.', 17),('01dbfc8f-dc91-4c8f-8208-30ba6a29b103'::uuid, '17b18678-1ec7-4938-8e2a-d696576e0c23'::uuid, 'multiple_choice', 'Which of the following is NOT listed as one of the four major landform regions of Africa in the excerpt?', 'Eurasian Plate', 'The excerpt lists African Alpine System, African massif, East African Highlands and rift system, and Southern Africa Platform as the four major landform regions; the Eurasian Plate is not one of them.', 18),('ffa52901-aea0-4d2c-8fed-f853dbcfa85b'::uuid, '17b18678-1ec7-4938-8e2a-d696576e0c23'::uuid, 'multiple_choice', 'Which of the following is NOT presented in the text as an effect of landforms on ecosystems?', 'Increase salinity of oceans', 'The excerpt lists several effects of landforms on ecosystems such as producing different patterns, affecting flows of organisms and disturbances by fire and wind; it does not mention increasing ocean salinity.', 19),('fbba6f4c-a41c-43a1-85ce-69d43f3216e9'::uuid, '17b18678-1ec7-4938-8e2a-d696576e0c23'::uuid, 'true_false', 'A peninsula is a piece of land that has water on three sides but it is connected on the fourth side to the mainland.', 'True', 'The excerpt defines a peninsula as land with water on three sides but connected to the mainland on the fourth side.', 20),('c60a6047-c5bf-456b-8593-43d54f7f4950'::uuid, '17b18678-1ec7-4938-8e2a-d696576e0c23'::uuid, 'true_false', 'Oceans together cover seventy one percent of the Earth.', 'True', 'The excerpt states that the oceans together cover seventy one percent of the Earth.', 21),('331b3cf5-f612-4a62-82ea-f388d0c8ad14'::uuid, '17b18678-1ec7-4938-8e2a-d696576e0c23'::uuid, 'true_false', 'Lake Victoria is found within the floor of the Great East African Rift valley.', 'False', 'The excerpt states that Lake Victoria is not in the rift valley but occupies a depression between the eastern and western rifts formed by uplift to either side.', 22),('7bf2a8ef-672b-4120-833f-af6075043dab'::uuid, '17b18678-1ec7-4938-8e2a-d696576e0c23'::uuid, 'true_false', 'The Sahara is the largest hot desert in the world with an area of 9,200,000 square kilometers.', 'True', 'The excerpt provides the Sahara''s area as 9,200,000 square kilometers and describes it as the largest hot desert in the world.', 23),('36f95835-edab-4ed8-8c3e-14a1c308ed37'::uuid, '17b18678-1ec7-4938-8e2a-d696576e0c23'::uuid, 'fill_blank', 'Name the three major types of landforms mentioned in the text.', 'Mountains; Plateaus; Plains', 'The excerpt explicitly states that the three major types of landforms are mountains, plateaus, and plains.', 24),('32cd18ba-1ae3-438a-8966-98212e557144'::uuid, '17b18678-1ec7-4938-8e2a-d696576e0c23'::uuid, 'fill_blank', 'What is an erg as described in the textbook?', 'A great sand sea formed by sand dunes', 'The excerpt describes an erg as a great sand sea made up of enormous quantities of sand dunes weathered from sandstone in the Sahara.', 25),('90a06faf-379e-4116-8fe8-99ffff186ff3'::uuid, '17b18678-1ec7-4938-8e2a-d696576e0c23'::uuid, 'fill_blank', 'Give two internal (endogenic) processes from the excerpt that create landforms.', 'Tectonic plate movement; Volcanic activities', 'The excerpt states that tectonic plate movement and volcanic activities (internal processes) in the Earth’s interior can create landforms by pushing up mountains and hills.', 26),('d0c9d8f7-92dd-4ff6-8013-b0dd1defa81e'::uuid, '17b18678-1ec7-4938-8e2a-d696576e0c23'::uuid, 'fill_blank', 'According to Table 1.1, list the four physical regions included under the African massif.', 'The Sahara; The Sahel; The Savanna; The Tropical rainforest', 'Table 1.1 in the excerpt lists those four physical regions under the African massif.', 27),('c4ab6fab-b6b7-4135-8c3f-096f3dc95dbb'::uuid, '17b18678-1ec7-4938-8e2a-d696576e0c23'::uuid, 'fill_blank', 'What is a graben as defined in the excerpt?', 'An elongated block of the earth’s crust lying between two faults and displaced downward relative to the blocks on either side', 'The excerpt defines a graben as an elongated block of crust between two faults that has been displaced downward, characteristic of rift valleys.', 28),('ae86cd47-e791-4d00-8164-0682d98f1a6e'::uuid, '17b18678-1ec7-4938-8e2a-d696576e0c23'::uuid, 'fill_blank', 'Name two deserts of Southern Africa mentioned in the text.', 'Kalahari Desert; Namib Desert', 'The excerpt names the Kalahari Desert (mainly in Botswana) and the Namib Desert (along the west coast of Namibia) as two important deserts of southern Africa.', 29),('307b5c7f-b36d-437d-8ba3-58062186faef'::uuid, '17b18678-1ec7-4938-8e2a-d696576e0c23'::uuid, 'fill_blank', 'Name the cold ocean current that borders and influenced the Namib Desert.', 'Benguela', 'The excerpt states that the Namib Desert was formed partly because of the cold ocean current of Benguela that borders the area.', 30),('a48421d8-e671-4df1-8c34-36f3ff4f3054'::uuid, '17b18678-1ec7-4938-8e2a-d696576e0c23'::uuid, 'fill_blank', 'Briefly explain how plateaus may form by volcanic activity according to the excerpt.', 'Magma pressure beneath the crust pushes the land upward without breaking the crust, raising a broad flat area to form a plateau', 'The excerpt explains that volcanic activity beneath the earth’s surface can push land upward when magma pressure is not strong enough to break through the crust, resulting in plateaus.', 31),('0ea39a19-1f44-4642-8ed4-9440c7a9e931'::uuid, '17b18678-1ec7-4938-8e2a-d696576e0c23'::uuid, 'fill_blank', 'What is the areal size of Africa as stated in the text?', '30.37 million Km2', 'The excerpt states Africa’s areal size is 30.37 million Km2.', 32),('7ca8dcd2-9f4d-4d9b-8cca-28fbdccf5085'::uuid, '17b18678-1ec7-4938-8e2a-d696576e0c23'::uuid, 'fill_blank', 'According to the excerpt, what percentage of the Earth’s total surface area is covered by oceans?', '71%', 'The excerpt indicates that the oceans together cover seventy one percent of the Earth.', 33),('e921de41-0d04-44cc-8408-2d4e59fb3dc3'::uuid, '17b18678-1ec7-4938-8e2a-d696576e0c23'::uuid, 'fill_blank', 'What area in square kilometers does the excerpt give for the Sahara Desert?', '9,200,000 square kilometers', 'The excerpt states that the Sahara has an area of 9,200,000 square kilometers and is the largest hot desert in the world.', 34),('d3b8cece-34ac-4159-8c6c-efb2a215f624'::uuid, '17b18678-1ec7-4938-8e2a-d696576e0c23'::uuid, 'fill_blank', 'What area in square kilometers does the excerpt give for Lake Victoria?', '68,800 square kilometers', 'The excerpt gives Lake Victoria an area of 68,800 square kilometers and notes it is the largest lake in Africa.', 35),('134eae77-3593-416c-8e12-9829ce46f9a1'::uuid, '17b18678-1ec7-4938-8e2a-d696576e0c23'::uuid, 'fill_blank', 'What is the total estimated length of the Rift Valley System as provided in the text?', '5,600 km', 'The excerpt estimates the total length of the Rift Valley System to be 5,600 km.', 36),('29f43235-fd92-405f-82b6-d6eb1827dc11'::uuid, '17b18678-1ec7-4938-8e2a-d696576e0c23'::uuid, 'fill_blank', 'What range for the average width of the Rift Valley System does the excerpt provide?', '32 km to 80 km', 'The excerpt states the average width of the Rift Valley System ranges between 32 km and 80 km.', 37),('c4a5d062-a161-4ad1-8515-5b46305be40d'::uuid, '17b18678-1ec7-4938-8e2a-d696576e0c23'::uuid, 'fill_blank', 'What is the height of Mt. Everest as stated in the excerpt?', '8,849 meters', 'The excerpt gives Mt. Everest''s height as 8,849 meters above sea level.', 38),('59484f0d-ad3d-45a4-855e-5c4893d26466'::uuid, '17b18678-1ec7-4938-8e2a-d696576e0c23'::uuid, 'fill_blank', 'According to the excerpt, about how many million years ago were the Himalayas formed?', '40 to 50 million years', 'The excerpt states the Himalayas were formed about 40 to 50 million years ago when the Indian tectonic plate collided with the Eurasian plate.', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDED.question_type, question_text = EXCLUDED.question_text, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, order_index = EXCLUDED.order_index;
